xql_query:
// ============================================================
// Rule: SLP_VA Cluster Status Change Event
// Vendor: SailPoint
// Objective:
// Detect activity associated with SLP_VA Cluster Status Change Event.
// Severity: SEV_040_HIGH
// Category: TAMPERING
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0006 - Credential Access

// Configuração inicial: comparações não diferenciam maiúsculas/minúsculas
config case_sensitive = false

// Fonte de dados: logs do SailPoint IdentityNow
// O dataset 'sailpoint_identitynow_raw' contém eventos de auditoria e atividades administrativas
// geradas pela plataforma (ex.: atualizações de fontes/conectores, mudanças de configuração, etc.)
| dataset = sailpoint_identitynow_raw

// Criação/normalização de campos para facilitar leitura e correlação
// - 'actor -> name' identifica o executor (usuário/identidade que realizou a ação)
// - '_metadata -> triggerId' contém a categoria/tipo do evento (ex.: "idn:source-updated")
| alter
    executor = actor -> name,                 // Executor da ação no IdentityNow
    category_raw = _metadata -> triggerId     // Categoria original do evento (com prefixo "idn:")

// Remoção do prefixo "idn:" da categoria
// Objetivo: padronizar a categoria para uso em alertas e dashboards
| alter
    category = replace(to_string(category_raw), "idn:", "")

// Filtro: monitora eventos de atualização de Source (fonte/conector) no IdentityNow
// "source-created" indica criação de conector/fonte
| filter category contains "Status Change"

// Seleção dos campos relevantes para auditoria e notificação do alerta
| fields
    category,            // Categoria normalizada do evento (sem "idn:")
    executor,            // Usuário que executou a alteração
    connector,           // Conector/fonte afetada (quando disponível no evento)
    name,                // Nome do objeto/fonte impactada
    type,                // Tipo do objeto alterado (ex.: source/connector)
    attributesUpdated    // Lista/descrição dos atributos que foram modificados
